41: func parse_escape_sequence(buf []byte) (size int, event KeyEvent) {
42: 	bufstr := string(buf)
43: 	for i, key := range keys {
44: 		if strings.HasPrefix(bufstr, key) {
45: 			event.Rune = 0
46: 			event.Key = Key(0xFFFF - i)
47: 			size = len(key)
48: 			return
49: 		}
50: 	}
51: 
52: 	// Might be an Alt combo in format of ESC+letter
53: 	if buf[0] == '\033' {
54: 		event.Key = KeyEsc
55: 		event.Rune, size = utf8.DecodeRune(buf[1:])
56: 		size = len(buf)
