178: func setup_term() (err error) {
179: 	var data []byte
180: 	var header [6]int16
181: 	var str_offset, table_offset int16
182: 
183: 	data, err = load_terminfo()
184: 	if err != nil {
185: 		return setup_term_builtin()
186: 	}
187: 
188: 	rd := bytes.NewReader(data)
189: 	// 0: magic number, 1: size of names section, 2: size of boolean section, 3:
190: 	// size of numbers section (in integers), 4: size of the strings section (in
191: 	// integers), 5: size of the string table
192: 
193: 	err = binary.Read(rd, binary.LittleEndian, header[:])
194: 	if err != nil {
195: 		return
196: 	}
197: 
198: 	if header[0] != 542 && header[0] != 282 {
199: 		return setup_term_builtin()
200: 	}
201: 
202: 	number_sec_len := int16(2)
203: 	if header[0] == 542 { // doc says it should be octal 0542, but what I see it terminfo files is 542, learn to program please... thank you..
204: 		number_sec_len = 4
205: 	}
206: 
207: 	if (header[1]+header[2])%2 != 0 {
208: 		// old quirk to align everything on word boundaries
209: 		header[2] += 1
210: 	}
211: 	str_offset = ti_header_length + header[1] + header[2] + number_sec_len*header[3]
212: 	table_offset = str_offset + 2*header[4]
213: 
214: 	keys = make([]string, 0xFFFF-key_min)
215: 	for i := range keys {
216: 		keys[i], err = ti_read_string(rd, str_offset+2*ti_keys[i], table_offset)
217: 		if err != nil {
218: 			return
219: 		}
220: 	}
221: 	return nil
222: }
