224: func ti_read_string(rd *bytes.Reader, str_off, table int16) (string, error) {
225: 	var off int16
226: 
227: 	_, err := rd.Seek(int64(str_off), 0)
228: 	if err != nil {
229: 		return "", err
230: 	}
231: 	err = binary.Read(rd, binary.LittleEndian, &off)
232: 	if err != nil {
233: 		return "", err
234: 	}
235: 	_, err = rd.Seek(int64(table+off), 0)
236: 	if err != nil {
237: 		return "", err
238: 	}
239: 	var bs []byte
240: 	for {
241: 		b, err := rd.ReadByte()
242: 		if err != nil {
243: 			return "", err
244: 		}
245: 		if b == byte(0x00) {
246: 			break
247: 		}
248: 		bs = append(bs, b)
249: 	}
250: 	return string(bs), nil
251: }
